{
  "contract": "Yeeter",
  "closure": {
    "site_function": "yeetyeet",
    "site_call": ".call",
    "functions": [
      "yeetyeet"
    ],
    "justification": "The function 'yeetyeet' is the only public function that writes to the exposed storage variables 'balance' and 'deposits'. The fallback function does not interact with storage and is therefore not included in the closure."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "yeetyeet"
    ],
    "nesting_bound": {
      "yeetyeet": 1
    }
  },
  "phases": {
    "function": "yeetyeet",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of deposits in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_deposits == balance + inFlight",
    "stable_formula": "_sum_deposits == balance",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_deposits == balance",
    "rule": "The exposure invariant ensures that the sum of deposits is conserved across the callback window, accounting for any in-flight changes."
  }
}
